import { Component, inject, OnInit, signal, computed } from '@angular/core';
import { ActivatedRoute, Router, RouterLink } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { ComiteService } from '../../../shared/services/comite.service';
import { SesionService } from '../../../shared/services/sesion.service';
import { ToastService } from '../../../shared/services/toast.service';
import { ToastContainerComponent } from '../../../shared/components/toast-container/toast-container.component';
import { MiembroComite, Comite } from '../../../shared/models/sesion.model';
import { NavigationHistoryService } from '../../../services/navigation-history.service';
import { extractErrorMessage } from '../../../shared/utils/error-utils';

@Component({
  selector: 'app-comite-designar',
  imports: [FormsModule, RouterLink, ToastContainerComponent],
  templateUrl: './comite-designar.component.html',
})
export class ComiteDesignarComponent implements OnInit {
  private route = inject(ActivatedRoute);
  private router = inject(Router);
  private comiteService = inject(ComiteService);
  private sesionService = inject(SesionService);
  private toastService = inject(ToastService);
  private navHistory = inject(NavigationHistoryService);

  readonly folio = this.route.snapshot.paramMap.get('folio') ?? '';
  readonly backRoute = computed(() => this.navHistory.getBackRoute('ejecutivo', 'dictaminacion'));

  readonly miembros = signal<MiembroComite[]>([]);
  readonly comiteExistente = signal<Comite | null>(null);
  readonly selectedIds = signal<Set<number>>(new Set());
  readonly loading = signal(false);
  readonly error = signal<string | null>(null);
  readonly comiteDesignado = signal<Comite | null>(null);
  readonly sesionCreada = signal(false);

  readonly fecha = signal('');
  readonly hora = signal('');
  readonly observaciones = signal('');

  readonly puedeDesignar = computed(
    () => !this.loading() && this.selectedIds().size > 0 && !this.comiteDesignado() && !this.comiteExistente(),
  );

  readonly puedeCrearSesion = computed(
    () =>
      !this.loading() &&
      this.fecha().length > 0 &&
      this.hora().length > 0 &&
      (this.comiteDesignado() != null || this.comiteExistente() != null),
  );

  ngOnInit(): void {
    this.comiteService.getMiembrosElegibles().subscribe({
      next: (data) => this.miembros.set(data),
      error: (err) => this.error.set(extractErrorMessage(err)),
    });
    this.comiteService.getComite(this.folio).subscribe({
      next: (comite) => {
        if (comite) this.comiteExistente.set(comite);
      },
      error: (err) => this.error.set(extractErrorMessage(err)),
    });
  }

  toggleMiembro(id: number): void {
    this.selectedIds.update(ids => {
      const next = new Set(ids);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  }

  onDesignar(): void {
    if (!this.puedeDesignar()) return;

    this.loading.set(true);
    this.error.set(null);

    const ids = Array.from(this.selectedIds());
    this.comiteService.designarComite(this.folio, ids).subscribe({
      next: (comite) => {
        this.loading.set(false);
        this.comiteDesignado.set(comite);
        this.toastService.success('Comité designado correctamente. La solicitud ha pasado a En Dictaminación.');
      },
      error: (err) => {
        this.loading.set(false);
        const errMsg = extractErrorMessage(err);
        this.error.set(errMsg);
        this.toastService.error(errMsg);
      },
    });
  }

  onCrearSesion(): void {
    if (!this.puedeCrearSesion()) return;

    const comite = this.comiteDesignado() ?? this.comiteExistente();
    if (!comite) return;

    this.loading.set(true);
    this.error.set(null);

    const payload = {
      fecha: this.fecha(),
      hora: this.hora(),
      observaciones: this.observaciones() || undefined,
    };

    this.sesionService.crearSesion(comite.id, payload).subscribe({
      next: () => {
        this.loading.set(false);
        this.sesionCreada.set(true);
        this.toastService.success('Sesión de comité programada correctamente.');
        this.router.navigate(['/ejecutivos/sesiones']);
      },
      error: (err) => {
        this.loading.set(false);
        const errMsg = extractErrorMessage(err);
        this.error.set(errMsg);
        this.toastService.error(errMsg);
      },
    });
  }
}
